    CODE_ISO             CHAR(3),
    NOM                  VARCHAR2(40),
    ANNEE_CREATION       NUMBER(4),
    ANNEE_DISPARITION    NUMBER(4),
    CONSTRAINT PK_RAL_PAYS PRIMARY KEY (CODE_PAYS)
);

